const crypto = require('crypto');
const { DynamoDBClient } = require('@aws-sdk/client-dynamodb');
const { DynamoDBDocumentClient, PutCommand, DeleteCommand } = require('@aws-sdk/lib-dynamodb');
const { SQSClient, SendMessageCommand } = require('@aws-sdk/client-sqs');
const shared = require('/opt/nodejs/shared');

// Module-scope clients, created once per warm environment (D-14 / D-40; the monolith
// built its DynamoDB client at module scope in utils/dynamodb.js:11-12).
const docClient = DynamoDBDocumentClient.from(new DynamoDBClient({}));
const sqsClient = new SQSClient({});

const ORDERS_TABLE = process.env.ORDERS_TABLE;
const CART_TABLE = process.env.CART_TABLE;
const BESTSELLER_QUEUE_URL = process.env.BESTSELLER_QUEUE_URL;

exports.handler = async function handler(event) {
  try {
    const body = shared.parseBody(event);
    const { books } = body;

    // routes/orders.js:49-54
    if (!books || !Array.isArray(books) || books.length === 0) {
      return shared.errorResponse(400, 'Missing or invalid books array');
    }

    const customerId = shared.customerId(event);

    // routes/orders.js:57 `const orderId = uuidv4();`
    const orderId = crypto.randomUUID();

    // 1. routes/orders.js:60-70 -- the order row, written first.
    const orderParams = {
      TableName: ORDERS_TABLE,
      Item: {
        customerId: customerId,
        orderId: orderId,
        orderDate: Date.now(),
        books: books,
      },
    };

    await docClient.send(new PutCommand(orderParams));

    // 2. routes/orders.js:72-83 -- clear the checked-out items from the cart:
    // one DeleteItem per element, all fired at once, awaited together.
    const deletePromises = books.map((book) => {
      const deleteParams = {
        TableName: CART_TABLE,
        Key: {
          customerId: customerId,
          bookId: book.bookId,
        },
      };
      return docClient.send(new DeleteCommand(deleteParams));
    });

    await Promise.all(deletePromises);

    // 3. routes/orders.js:85-98 -- the bestseller update, now a message (D-3).
    // Awaited so it survives the freeze (D-36); a failure is only logged, because the
    // order response never depends on it (#business_rules[7]).
    try {
      await sqsClient.send(new SendMessageCommand({
        QueueUrl: BESTSELLER_QUEUE_URL,
        MessageBody: JSON.stringify({
          orderId: orderId,
          books: books.map((book) => ({ bookId: book.bookId, quantity: book.quantity })),
        }),
      }));
    } catch (sendError) {
      console.error('Error queueing bestseller update:', sendError);
    }

    // routes/orders.js:99-102
    return shared.response(200, {
      message: 'Order created successfully',
      orderId: orderId,
    });
  } catch (error) {
    console.error('Error in POST /orders:', error);
    return shared.fromException(error);
  }
};

