const { DynamoDBDocumentClient, ScanCommand } = require('@aws-sdk/lib-dynamodb');
const shared = require('/opt/nodejs/shared');

const docClient = DynamoDBDocumentClient.from(new DynamoDBClient({}));

const BOOKS_TABLE = process.env.BOOKS_TABLE;

exports.handler = async function handler(event) {
  try {
    // routes/search.js:17 -- `const query = req.query.q;` (the name is load-bearing, see
    // the header comment: the TypeError's message quotes this expression).
    const query = shared.queryValue(event, 'q');

    // routes/search.js:19-23
