 * `updateBestSellers`), which `routes/orders.js:87` called without awaiting and whose
 * return value nobody used (GAP-2). Spec basis: blueprint.lambda_functions[update-bestsellers]
 * .notes, `storage/DECISIONS.md` D-3 / D-20, and the rules it cites:
 * `POST /api/orders#business_rules[6]`, `[9]` (contract, SI-17), `[7]`, `[8]`
 * (implementation-trace, SI-8 / SI-9).
 *
 * REQUIRED correctness rule: consumers must be idempotent under redelivery
 * (m2s-async-patterns-kb). Mechanism chosen by the architect, not invented here:
 * **Pattern A** -- a dedupe marker and the salesCount increments commit in ONE
 * TransactWriteItems:
 *   - marker: PutItem IdempotencyTable `{pk:'update-bestsellers#<orderId>',
 *     expiresAt: now + 7d}` (epoch seconds; the TTL lives on the target-only
 *     IdempotencyTable, blueprint dynamodb_tables[IdempotencyTable]) with
 *     `ConditionExpression: 'attribute_not_exists(pk)'`;
 *   - then one `Update ADD salesCount` per merged entry of BestsellersTable.
 * The idempotency key is the `orderId` the producer carries in the body (D-3); the SQS
 * `messageId` is not used for dedupe (a producer retry of SendMessage would get a new one).
 *
 * Merging the same bookId first (`qtyByBook`) is required: a transaction may not contain
 * two operations on one item, and the summed result equals the monolith's per-book
 * `ADD`s, which is what `POST /api/orders#business_rules[9]` makes observable (an order
 * with the same book twice adds its quantity once, total unchanged).
 *
 * Only numeric quantities are added (`POST /api/orders#business_rules[6]`): in the
 * monolith an element whose `quantity` is missing / a string / a boolean / null made
 * DynamoDB reject that `ADD`, and `utils/bestsellers.js:31-34` swallowed the error, so
 * the book's salesCount stayed unchanged (and a non-existent entry stayed non-existent,
 * case `wb-order-qty-not-number`); entries without a `bookId` were rejected the same way
 * (`#business_rules[10]`). Skipping them here reproduces that external outcome.
 *
 * Batching (D-3): more than 99 merged entries are split into chunks of at most 99
 * effects, in first-appearance order of the merged keys, each chunk carrying **its own**
 * marker `update-bestsellers#<orderId>#<chunk index>` -- so a redelivery after a partial
 * commit skips the committed chunks and applies the rest exactly once.
 *
 * Failure policy chosen by D-3: **(b) report** -- a chunk that is not a duplicate and
 * still fails after bounded retries makes this message appear in `batchItemFailures`
 * (the template puts `FunctionResponseTypes: [ReportBatchItemFailures]` on the event
 * source; 3 receives then DLQ). A `TransactionConflict` cancellation is a transient
 * failure and is retried with bounded backoff (max 3) and then reported -- swallowing it
 * would invent a lost-update mode the monolith never had. Malformed messages (unparsable
 * body, or no `orderId`) are logged and skipped like the monolith swallowed its
 * background failures; they are not failures.
 *
 * Shape of the rows written: `salesCount` only -- nothing else is ever written to
 * BestsellersTable (blueprint notes / adapter_map), so a book created by an order looks
 * exactly like one created by the monolith.
 *
 * This is an SQS-triggered function: it returns no API Gateway response object, and
 * reads no `claims` (the ranking is shared data and the message carries no identity).
 */

const { DynamoDBClient } = require('@aws-sdk/client-dynamodb');
const { DynamoDBDocumentClient, TransactWriteCommand } = require('@aws-sdk/lib-dynamodb');

const docClient = DynamoDBDocumentClient.from(new DynamoDBClient({}));

// Table names come only from this function's environment_variables (D-39).
const BESTSELLERS_TABLE = process.env.BESTSELLERS_TABLE;
const IDEMPOTENCY_TABLE = process.env.IDEMPOTENCY_TABLE;

const CONSUMER = 'update-bestsellers';
const MAX_EFFECTS = 99;         // 100 operations per transaction, minus the marker
const MAX_RETRIES = 3;          // bounded backoff for transient failures
const MARKER_TTL_SECONDS = 7 * 86400; // > the queue's 4-day retention (D-3)

function sleep(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

/**
 * Merge the message's `books` into one increment per bookId, in first-appearance order.
 * Only entries the monolith's single `ADD` would have accepted survive: a `bookId` that
 * is not a non-empty string, or a `quantity` that is not a finite JS number, was rejected
 * by DynamoDB and swallowed -- so it must not change salesCount here either.
 */
function mergeQuantities(books) {
  const qtyByBook = new Map();
  for (const book of books) {
    if (!book || typeof book !== 'object') {
      continue;
    }
    const bookId = book.bookId;
    const quantity = book.quantity;
    if (typeof bookId !== 'string' || bookId.length === 0) {
      continue;
    }
    if (typeof quantity !== 'number' || !Number.isFinite(quantity)) {
      continue;
    }
    qtyByBook.set(bookId, (qtyByBook.get(bookId) || 0) + quantity);
  }
  return qtyByBook;
}

/**
 * The chunks for one message: [marker, ...effects] per chunk, each chunk with its own
 * marker so a partially committed message can be redelivered safely.
 */
function transactionChunks(orderId, qtyByBook) {
  const entries = [...qtyByBook];
  const updates = entries.map(([bookId, quantity]) => ({
    Update: {
      TableName: BESTSELLERS_TABLE,
      Key: { bookId: bookId },
      UpdateExpression: 'ADD salesCount :qty',
      ExpressionAttributeValues: { ':qty': quantity },
    },
  }));

  const chunks = [];
  for (let i = 0; i < updates.length; i += MAX_EFFECTS) {
    chunks.push(updates.slice(i, i + MAX_EFFECTS));
  }

  const expiresAt = Math.floor(Date.now() / 1000) + MARKER_TTL_SECONDS;
  return chunks.map((chunk, index) => {
    const pk = chunks.length > 1 ? `${CONSUMER}#${orderId}#${index}` : `${CONSUMER}#${orderId}`;
    const marker = {
      Put: {
        TableName: IDEMPOTENCY_TABLE,
        Item: { pk: pk, expiresAt: expiresAt },
        ConditionExpression: 'attribute_not_exists(pk)',
      },
    };
    return [marker, ...chunk]; // marker first: a duplicate shows up in CancellationReasons[0]
  });
}

/**
 * Classify a failed TransactWriteItems the way D-3 says:
 *  - 'duplicate'  : the chunk's own marker already exists -> this delivery already
 *                   committed it, nothing to do;
 *  - 'retryable'  : TransactionConflict (another transaction on one of the same items is
 *                   in flight) -- a transient failure, never swallowed;
 *  - 'permanent'  : any other cancellation.
 * (A TransactionCanceledException is the client-side name of DynamoDB's
 * TransactionInProgressException here: `err.name` + `err.CancellationReasons`.)
 */
function classify(err) {
  const name = (err && (err.name || err.__type)) || '';
  if (name.indexOf('TransactionCanceledException') !== -1 || name.indexOf('TransactionInProgressException') !== -1) {
    const reasons = (err && err.CancellationReasons) || [];
    if (reasons.length > 0 && reasons[0] && reasons[0].Code === 'ConditionalCheckFailed') {
      return 'duplicate';
    }
    if (reasons.some((reason) => reason && reason.Code === 'TransactionConflict')) {
      return 'retryable';
    }
    return 'permanent';
  }
  return 'permanent';
}

/**
 * Apply one chunk with bounded backoff. Returns 'applied' | 'duplicate' | 'failed'.
 */
async function applyChunk(items) {
  for (let attempt = 0; attempt <= MAX_RETRIES; attempt += 1) {
    if (attempt > 0) {
      // ~50ms doubling capped at 800ms, plus jitter (a conflict means somebody else
      // committed the same item a moment ago).
      await sleep(Math.min(50 * 2 ** (attempt - 1), 800) + Math.floor(Math.random() * 50));
    }
    try {
      await docClient.send(new TransactWriteCommand({ TransactItems: items }));
      return 'applied';
    } catch (err) {
      const kind = classify(err);
      if (kind === 'duplicate') {
        console.log(`${CONSUMER}: message already applied, skipping chunk (${String(err && err.message)})`);
        return 'duplicate';
      }
      if (kind === 'retryable') {
        console.warn(`${CONSUMER}: transaction conflict, attempt ${attempt + 1}/${MAX_RETRIES + 1}`);
        continue;
      }
      console.error(`${CONSUMER}: transaction failed:`, err);
      return 'failed';
    }
  }
  return 'failed'; // conflict on every attempt: report it, redelivery is safe (Pattern A)
}

/**
 * Apply one message. Returns 'applied' | 'duplicate' | 'failed'.
 */
async function applyMessage(orderId, books) {
  const chunks = transactionChunks(orderId, mergeQuantities(books));
  if (chunks.length === 0) {
    // Nothing this message may add (every element was rejected in the monolith too:
    // empty books, or only non-numeric quantities). Still mark the orderId so a
    // redelivery cannot be confused with a first delivery.
    await applyChunk(transactionChunks(orderId, new Map([undefined]))[0] && []);
    return 'applied';
  }
  let duplicates = 0;
  for (const items of chunks) {
    const outcome = await applyChunk(items);
    if (outcome === 'failed') {
      return 'failed';
    }
    if (outcome === 'duplicate') {
      duplicates += 1;
    }
  }
  return duplicates === chunks.length ? 'duplicate' : 'applied';
}

exports.handler = async function handler(event) {
  const failures = [];

  for (const record of (event && event.Records) || []) {
    let orderId;
    let books;
    try {
      const payload = JSON.parse(record.body);
      orderId = payload.orderId;
      books = payload.books;
      if (!orderId) {
        throw new Error('missing orderId');
      }
      if (!Array.isArray(books)) {
        throw new Error('missing or invalid books');
      }
    } catch (parseError) {
      // D-3: the monolith swallowed its background failures, so an unparsable message is
      // logged and skipped -- and NOT reported as a failure (that would spin it to the DLQ
      // for something the monolith would never have retried).
      console.error(`${CONSUMER}: skipping malformed message ${record.messageId}:`, parseError);
      continue;
    }

    if (books.length === 0) {
      // routes/orders.js -> utils/bestsellers.js:41-43: an empty list was a no-op.
      console.log(`${CONSUMER}: order ${orderId} has no books, nothing to add`);
      continue;
    }

    const outcome = await applyMessage(orderId, books);
    console.log(`${CONSUMER}: order ${orderId} -> ${outcome}`);
    if (outcome === 'failed') {
      // Failure policy (b): report it so SQS redelivers (idempotency makes that safe),
      // then DLQ after maxReceiveCount=3. Never swallow a transient failure.
      failures.push({ itemIdentifier: record.messageId });
    }
  }

  return { batchItemFailures: failures };
};

