const CONSUMER = 'update-bestsellers';
const MAX_EFFECTS = 99;         // 100 operations per transaction, minus the marker
const MAX_RETRIES = 3;          // bounded backoff for transient failures
const MARKER_TTL_SECONDS = 7 * 86400; // > the queue's 4-day retention (D-3)

function sleep(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

/**
 * Merge the message's `books` into one increment per bookId, in first-appearance order.
 * Only entries the monolith's single `ADD` would have accepted survive: a `bookId` that
 * is not a non-empty string, or a `quantity` that is not a finite JS number, was rejected
 * by DynamoDB and swallowed -- so it must not change salesCount here either.
 */
function mergeQuantities(books) {
  const qtyByBook = new Map();
  for (const book of books) {
    if (!book || typeof book !== 'object') {
      continue;
    }
    const bookId = book.bookId;
    const quantity = book.quantity;
    if (typeof bookId !== 'string' || bookId.length === 0) {
      continue;
    }
    if (typeof quantity !== 'number' || !Number.isFinite(quantity)) {
      continue;
    }
    qtyByBook.set(bookId, (qtyByBook.get(bookId) || 0) + quantity);
  }
  return qtyByBook;
}

/**
 * The chunks for one message: [marker, ...effects] per chunk, each chunk with its own
 * marker so a partially committed message can be redelivered safely.
 */
function transactionChunks(orderId, qtyByBook) {
  const entries = [...qtyByBook];
  const updates = entries.map(([bookId, quantity]) => ({
    Update: {
      TableName: BESTSELLERS_TABLE,
      Key: { bookId: bookId },
      UpdateExpression: 'ADD salesCount :qty',
      ExpressionAttributeValues: { ':qty': quantity },
    },
  }));

  const chunks = [];
  for (let i = 0; i < updates.length; i += MAX_EFFECTS) {
    chunks.push(updates.slice(i, i + MAX_EFFECTS));
  }

  const expiresAt = Math.floor(Date.now() / 1000) + MARKER_TTL_SECONDS;
  return chunks.map((chunk, index) => {
    const pk = chunks.length > 1 ? `${CONSUMER}#${orderId}#${index}` : `${CONSUMER}#${orderId}`;
    const marker = {
      Put: {
        TableName: IDEMPOTENCY_TABLE,
        Item: { pk: pk, expiresAt: expiresAt },
        ConditionExpression: 'attribute_not_exists(pk)',
      },
    };
    return [marker, ...chunk]; // marker first: a duplicate shows up in CancellationReasons[0]
  });
}

/**
 * Classify a failed TransactWriteItems the way D-3 says:
 *  - 'duplicate'  : the chunk's own marker already exists -> this delivery already
 *                   committed it, nothing to do;
 *  - 'retryable'  : TransactionConflict (another transaction on one of the same items is
 *                   in flight) -- a transient failure, never swallowed;
 *  - 'permanent'  : any other cancellation.
 * (A TransactionCanceledException is the client-side name of DynamoDB's
 * TransactionInProgressException here: `err.name` + `err.CancellationReasons`.)
 */
function classify(err) {
  const name = (err && (err.name || err.__type)) || '';
  if (name.indexOf('TransactionCanceledException') !== -1 || name.indexOf('TransactionInProgressException') !== -1) {
    const reasons = (err && err.CancellationReasons) || [];
    if (reasons.length > 0 && reasons[0] && reasons[0].Code === 'ConditionalCheckFailed') {
      return 'duplicate';
    }
    if (reasons.some((reason) => reason && reason.Code === 'TransactionConflict')) {
      return 'retryable';
    }
    return 'permanent';
  }
  return 'permanent';
}

/**
 * Apply one chunk with bounded backoff. Returns 'applied' | 'duplicate' | 'failed'.
 */
async function applyChunk(items) {
  for (let attempt = 0; attempt <= MAX_RETRIES; attempt += 1) {
    if (attempt > 0) {
      // ~50ms doubling capped at 800ms, plus jitter (a conflict means somebody else
      // committed the same item a moment ago).
      await sleep(Math.min(50 * 2 ** (attempt - 1), 800) + Math.floor(Math.random() * 50));
    }
    try {
      await docClient.send(new TransactWriteCommand({ TransactItems: items }));
      return 'applied';
    } catch (err) {
      const kind = classify(err);
      if (kind === 'duplicate') {
        console.log(`${CONSUMER}: message already applied, skipping chunk (${String(err && err.message)})`);
        return 'duplicate';
      }
      if (kind === 'retryable') {
        console.warn(`${CONSUMER}: transaction conflict, attempt ${attempt + 1}/${MAX_RETRIES + 1}`);
        continue;
      }
      console.error(`${CONSUMER}: transaction failed:`, err);
      return 'failed';
    }
  }
  return 'failed'; // conflict on every attempt: report it, redelivery is safe (Pattern A)
}

