async function applyMessage(orderId, books) {
  const merged = mergeQuantities(books);
  if (merged.size === 0) {
    // Nothing in this message may add to a counter: every element was one the monolith's
    // single ADD rejected as well (no usable bookId, or a quantity that is not a number),
    // so salesCount stays as it is and there is no effect to deduplicate.
    return 'applied';
  }

  const chunks = transactionChunks(orderId, merged);
  let duplicates = 0;
  for (const items of chunks) {
    const outcome = await applyChunk(items);
    if (outcome === 'failed') {
      return 'failed';
    }
    if (outcome === 'duplicate') {
      duplicates += 1;
    }
  }
  return duplicates === chunks.length ? 'duplicate' : 'applied';
}

