      // logged and skipped -- and NOT reported as a failure (that would spin it to the DLQ
      // for something the monolith would never have retried).
      console.error(`${CONSUMER}: skipping malformed message ${record.messageId}:`, parseError);
      continue;
    }

    if (books.length === 0) {
      // routes/orders.js -> utils/bestsellers.js:41-43: an empty list was a no-op.
      console.log(`${CONSUMER}: order ${orderId} has no books, nothing to add`);
      continue;
